from __future__ import annotations

import shutil
import time
from pathlib import Path
from typing import Any, NamedTuple, Optional

import structlog
from duoname import duoname
from tarsafe import TarSafe

from rasa.engine.graph import GraphModelConfiguration, GraphSchema
from rasa.engine.storage.local_model_storage import (
    LocalModelStorage,
    windows_safe_temporary_directory,
)
from rasa.mantle.config.agent_spec import agent_spec_from_config
from rasa.mantle.content.responses import RESPONSES_FILENAME
from rasa.mantle.hooks.constants import HOOKS_DIR_NAME, HOOKS_FILE_NAME
from rasa.mantle.model_archive.references_index import build_references_index
from rasa.mantle.model_archive.skills_index import build_skills_index
from rasa.mantle.model_archive.training_telemetry import (
    build_mantle_training_started_attributes,
)
from rasa.mantle.tools.loader import TOOLS_DIR_NAME
from rasa.shared.constants import CONFIG_ADDITIONAL_LANGUAGES_KEY
from rasa.shared.core.domain import Domain
from rasa.shared.data import TrainingType
from rasa.shared.engine_version import MANTLE_ENGINE_VERSION
from rasa.shared.project_structure import (
    MANTLE_AGENT_FILE,
    MANTLE_REFERENCES_DIR,
    MANTLE_SNAPSHOT_DIR,
)
from rasa.shared.utils.yaml import read_config_file

structlogger = structlog.get_logger(__name__)

# Project source files copied verbatim into the snapshot.
V2_SNAPSHOT_SOURCE_FILES = (
    "integrations.yml",
    "memory.yml",
    RESPONSES_FILENAME,
)

# Project source directories copied verbatim into the snapshot. ``skills/``
# carries each skill's own ``tools/`` (and per-skill ``references/``); the root
# ``tools/`` holds shared tools and ``references/`` the global knowledge files.
V2_SNAPSHOT_SOURCE_DIRS = ("skills", "lib", TOOLS_DIR_NAME, MANTLE_REFERENCES_DIR)


class PackageTrainingResult(NamedTuple):
    """Training result shape compatible with `rasa.model_training.TrainingResult`."""

    model: Optional[str] = None
    code: int = 0
    dry_run_results: Optional[Any] = None


def _read_config_for_telemetry(config_path: str) -> Optional[dict]:
    """Best-effort read of the agent config for the started event (never raises)."""
    try:
        return read_config_file(config_path)
    except Exception:
        return None


def _telemetry_identity(
    config_data: Optional[dict],
) -> tuple[Optional[str], Optional[str]]:
    """Return best-effort ``(assistant_id, language)`` from a raw agent config.

    Reads the raw ``agent:`` mapping directly rather than parsing an
    :class:`AgentSpec`, so a project that fails spec validation (e.g. a missing
    persona) still contributes identity to the started event before it fails.
    """
    if not isinstance(config_data, dict):
        return None, None
    agent_section = config_data.get("agent")
    if not isinstance(agent_section, dict):
        return None, None
    return agent_section.get("id"), agent_section.get("language")


def _determine_package_model_name(fixed_model_name: Optional[str]) -> str:
    if fixed_model_name:
        if not fixed_model_name.endswith(".tar.gz"):
            return f"{fixed_model_name}.tar.gz"
        return fixed_model_name

    time_format = "%Y%m%d-%H%M%S"
    return f"{time.strftime(time_format)}-{duoname()}.tar.gz"


def populate_snapshot(
    snapshot_root: Path,
    project_root: Path,
    config_path: Path,
) -> None:
    """Copy project files into a snapshot directory.

    Copies the project agent config (stored as ``agent.yml`` in the snapshot),
    the top-level source files listed in :data:`V2_SNAPSHOT_SOURCE_FILES`
    (``integrations.yml``, ``memory.yml``, ``responses.yml`` — all optional),
    the entire ``skills/`` tree, the optional ``lib/`` directory (shared
    Python code — the tool loader puts the snapshot root on ``sys.path``
    during tool import, so a tool module at any location imports it via
    ``from lib.<module> import ...``), and the optional shared ``tools/``
    folder (``@tool`` functions available across skills).
    Missing files and directories are silently skipped.

    The on-disk project file passed as *config_path* is typically ``agent.yml``
    (see :data:`~rasa.shared.project_structure.MANTLE_AGENT_FILE`); its contents are
    packaged as ``agent.yml`` in the archive.
    """
    snapshot_root.mkdir(parents=True, exist_ok=True)

    if config_path.is_file():
        shutil.copy2(config_path, snapshot_root / MANTLE_AGENT_FILE)

    for file_name in V2_SNAPSHOT_SOURCE_FILES:
        source = project_root / file_name
        if source.is_file():
            shutil.copy2(source, snapshot_root / file_name)

    # Directory trees: skills/ (carrying each skill's own tools/), the optional
    # shared lib/, and the shared root tools/. __pycache__/*.pyc are developer
    # byproducts and must not be packaged into the archive.
    for dir_name in V2_SNAPSHOT_SOURCE_DIRS:
        source = project_root / dir_name
        if source.is_dir():
            shutil.copytree(
                source,
                snapshot_root / dir_name,
                dirs_exist_ok=True,
                ignore=shutil.ignore_patterns("__pycache__", "*.pyc"),
            )

    hooks_file = project_root / HOOKS_FILE_NAME
    if hooks_file.is_file():
        shutil.copy2(hooks_file, snapshot_root / HOOKS_FILE_NAME)

    hooks_dir = project_root / HOOKS_DIR_NAME
    if hooks_dir.is_dir():
        shutil.copytree(
            hooks_dir,
            snapshot_root / HOOKS_DIR_NAME,
            dirs_exist_ok=True,
            ignore=shutil.ignore_patterns("__pycache__", "*.pyc"),
        )


def package_model_archive(
    config_path: str,
    output: str,
    fixed_model_name: Optional[str] = None,
    validate: bool = True,
) -> PackageTrainingResult:
    """Package a project into a deployable archive without graph training.

    Copies the project source files (packaged ``agent.yml``, optional
    ``integrations.yml``, ``memory.yml``, ``responses.yml``, and the entire
    ``skills/`` tree) into a model archive under ``mantle_snapshot/``.
    No compilation step is performed — the runtime reads the primitives
    directly from the snapshot at model-load time.

    Args:
        config_path: Path to the project's ``config.yml``.
        output: Directory the packaged model archive is written to.
        fixed_model_name: Optional fixed name for the produced model archive.
        validate: When ``True`` (the default), run project validation before
            packaging so a misconfigured project fails at train time. Set
            ``False`` to honour ``rasa train --skip-validation``.
    """
    import rasa.telemetry as telemetry

    config_file = Path(config_path)
    project_root = config_file.parent

    telemetry_config = _read_config_for_telemetry(config_path)
    assistant_id, language = _telemetry_identity(telemetry_config)

    def _started_attributes() -> dict:
        attributes = build_mantle_training_started_attributes(
            project_root, telemetry_config
        )
        attributes.setdefault("language", language)
        return attributes

    with telemetry.track_mantle_model_training(
        assistant_id, _started_attributes
    ) as training:
        # Validate authoring (flow structure, memory declarations, tools, ...)
        # before packaging so a misconfigured project fails at train time, not
        # mid-conversation.
        training.set_stage("validation")
        if validate:
            from rasa.mantle.validation import validate_project

            validate_project(project_root)

        training.set_stage("config")
        # Re-read after validation: validate_project may generate and write a
        # missing agent.id back to agent.yml, so the pre-validation telemetry read
        # (telemetry_config) is stale here and must not drive packaging.
        config_data = read_config_file(config_path)
        agent_spec = agent_spec_from_config(config_data)
        # Refresh the telemetry id with the post-validation value so the
        # completed/failed events report the id that was actually packaged.
        training.set_assistant_id(agent_spec.id)

        training.set_stage("packaging")
        # The engine owns its slot names via the memory layer; the runtime tracker is
        # permissive (AnySlotDict) and accepts namespaced writes on demand, so no
        # tracker-slot domain needs to be generated or packaged. We still package an
        # empty (non-None) domain because shared infra (tracker stores, session
        # handling) reads `domain.session_config` / `domain.slots` unconditionally;
        # the v2 turn itself never reads the domain.
        domain = Domain.empty()

        model_name = _determine_package_model_name(fixed_model_name)
        output_path = Path(output)
        output_path.mkdir(parents=True, exist_ok=True)
        full_model_path = output_path / model_name

        model_configuration = GraphModelConfiguration(
            train_schema=GraphSchema({}),
            predict_schema=GraphSchema({}),
            training_type=TrainingType.BOTH,
            assistant_id=agent_spec.id,
            language=agent_spec.language,
            core_target=None,
            nlu_target=None,
            additional_languages=config_data.get(CONFIG_ADDITIONAL_LANGUAGES_KEY),
            engine_version=MANTLE_ENGINE_VERSION,
        )

        with windows_safe_temporary_directory(prefix="mantle-package-") as temp_dir:
            temp_dir_path = Path(temp_dir)
            storage_path = temp_dir_path / "storage"
            storage_path.mkdir(parents=True, exist_ok=True)

            model_storage = LocalModelStorage(storage_path)
            metadata = model_storage.create_model_package(
                full_model_path,
                model_configuration,
                domain,
            )
            training.set_model_id(metadata.model_id)

            extracted = temp_dir_path / "extracted"
            extracted.mkdir(parents=True, exist_ok=True)
            with TarSafe.open(full_model_path, mode="r:gz") as tar:
                tar.extractall(extracted)

            snapshot_root = extracted / MANTLE_SNAPSHOT_DIR
            populate_snapshot(
                snapshot_root=snapshot_root,
                project_root=project_root,
                config_path=config_file,
            )
            # Build the local FAISS index from packaged references/ (no-op when the
            # project ships no reference files).
            training.set_stage("references_index")
            build_references_index(
                snapshot_root=snapshot_root,
                project_root=project_root,
            )
            training.set_stage("skills_index")
            build_skills_index(
                snapshot_root=snapshot_root,
                project_root=project_root,
            )
            training.set_stage("packaging")

            with TarSafe.open(full_model_path, "w:gz") as tar:
                tar.add(extracted, arcname="")

        structlogger.info(
            "mantle.model_archive.snapshot.package_model_archive.finished",
            event_info=f"Mantle model package saved at '{full_model_path}'.",
            model_id=metadata.model_id,
        )

        return PackageTrainingResult(model=str(full_model_path), code=0)
